local MosaicTileMaker = {}
local PRODUCTS = {
    simple_clay_mosaic = { name = "Preprosta glinena mozaike", clayCost = 2, glassCost = 1, time = 4, cost = 60, beauty = 22, happiness = 1, description = "Preprosta glinena mozaike za tla." },
    glass_tessera_mosaic = { name = "Steklena tesera mozaike", glassCost = 3, clayCost = 1, time = 7, cost = 180, beauty = 38, happiness = 2, prestige = 2, description = "Steklena tesera mozaike za trgovce." },
    marble_inlaid_mosaic = { name = "Marmornatavložena mozaike", marbleCost = 2, glassCost = 2, clayCost = 1, time = 10, cost = 460, beauty = 52, happiness = 2, prestige = 6, description = "Marmornatavložena mozaike za plemiče." }
    , silver_band_mosaic = { name = "Srebrnopasna mozaike", marbleCost = 2, silverCost = 1, glassCost = 2, clayCost = 1, time = 14, cost = 1100, beauty = 65, happiness = 3, prestige = 14, description = "Srebrnopasna mozaike za visoke plemiče." },
    gold_leaf_mosaic = { name = "Zlatolistna mozaike", marbleCost = 2, goldCost = 1, silverCost = 1, glassCost = 2, clayCost = 1, jewelCost = 1, time = 18, cost = 2400, beauty = 78, happiness = 5, prestige = 27, description = "Zlatolistna mozaike z draguljem za visoko plemstvo." },
    royal_grand_mosaic = { name = "Kraljevski veliki mozaike", marbleCost = 3, goldCost = 2, silverCost = 2, glassCost = 3, clayCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 5500, beauty = 92, happiness = 12, prestige = 58, description = "Velika kraljevska mozaike z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    mosaic_workshop = { name = "Mozaikna delavnica", cost = { gold = 260, wood = 100, stone = 140, clay = 6, glass = 6 }, upkeep = 6, qualityBonus = 5 },
    tessera_loft = { name = "Teserska podstrešje", cost = { gold = 950, wood = 240, stone = 280, marble = 4, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    master_mosaic_atelier = { name = "Mojstrski mozaikni atelje", cost = { gold = 2700, wood = 360, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_mosaic_palace = { name = "Kraljevska mozaikna palača", cost = { gold = 11500, wood = 580, stone = 800, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
MosaicTileMaker.clayStock = 14; MosaicTileMaker.glassStock = 14; MosaicTileMaker.marbleStock = 10; MosaicTileMaker.silverStock = 6; MosaicTileMaker.goldStock = 6; MosaicTileMaker.jewelStock = 4; MosaicTileMaker.pearlStock = 4
MosaicTileMaker.productStock = {}; MosaicTileMaker.buildings = {}; MosaicTileMaker.maker = nil; MosaicTileMaker.activeMaking = {}; MosaicTileMaker.totalProducts = 0; MosaicTileMaker.dayTimer = 0
function MosaicTileMaker.init() MosaicTileMaker.clayStock=14; MosaicTileMaker.glassStock=14; MosaicTileMaker.marbleStock=10; MosaicTileMaker.silverStock=6; MosaicTileMaker.goldStock=6; MosaicTileMaker.jewelStock=4; MosaicTileMaker.pearlStock=4; MosaicTileMaker.productStock={}; MosaicTileMaker.buildings={}; MosaicTileMaker.maker=nil; MosaicTileMaker.activeMaking={}; MosaicTileMaker.totalProducts=0; MosaicTileMaker.dayTimer=0; print("[MosaicTileMaker] Royal Mosaic Tile Maker System initialized (6 products, 4 buildings)") end
function MosaicTileMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MosaicTileMaker.maker={name=n or ("Mozaikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mozaikar najet: %s (spretnost: %d)",MosaicTileMaker.maker.name,s),"success") end; return true end
function MosaicTileMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MosaicTileMaker.build(id) local ok,e=MosaicTileMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MosaicTileMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MosaicTileMaker.getQualityBonus() local b=0; for _,bd in ipairs(MosaicTileMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MosaicTileMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and MosaicTileMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.glassCost and MosaicTileMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.marbleCost and MosaicTileMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and MosaicTileMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MosaicTileMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MosaicTileMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MosaicTileMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MosaicTileMaker.buildings==0 then return false,"Potrebna mozaikna delavnica" end; if not MosaicTileMaker.maker then return false,"Potreben mozaikar" end; return true end
function MosaicTileMaker.make(pt,qty) qty=qty or 1; local ok,e=MosaicTileMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then MosaicTileMaker.clayStock=MosaicTileMaker.clayStock-d.clayCost*qty end; if d.glassCost then MosaicTileMaker.glassStock=MosaicTileMaker.glassStock-d.glassCost*qty end; if d.marbleCost then MosaicTileMaker.marbleStock=MosaicTileMaker.marbleStock-d.marbleCost*qty end; if d.silverCost then MosaicTileMaker.silverStock=MosaicTileMaker.silverStock-d.silverCost*qty end; if d.goldCost then MosaicTileMaker.goldStock=MosaicTileMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MosaicTileMaker.jewelStock=MosaicTileMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MosaicTileMaker.pearlStock=MosaicTileMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MosaicTileMaker.maker then t=math.max(1,t-math.floor(MosaicTileMaker.maker.skill/12)) end; table.insert(MosaicTileMaker.activeMaking,{id="mosaic_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polaganje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MosaicTileMaker.completeMaking(m) local q=1.0+(MosaicTileMaker.getQualityBonus()/100); if MosaicTileMaker.maker then q=q+(MosaicTileMaker.maker.skill/140) end; q=math.min(2.5,q); MosaicTileMaker.productStock[m.productType]=(MosaicTileMaker.productStock[m.productType] or 0)+m.quantity; MosaicTileMaker.totalProducts=MosaicTileMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MosaicTileMaker.maker then MosaicTileMaker.maker.itemsMade=MosaicTileMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MosaicTileMaker.maker.skill=math.min(100,MosaicTileMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mozaike izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mosaic.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function MosaicTileMaker.update(dt) if not _G.state then return end; MosaicTileMaker.dayTimer=MosaicTileMaker.dayTimer+dt; if MosaicTileMaker.dayTimer>=30 then MosaicTileMaker.dayTimer=0; for i=#MosaicTileMaker.activeMaking,1,-1 do local m=MosaicTileMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MosaicTileMaker.completeMaking(m); table.remove(MosaicTileMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MosaicTileMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MosaicTileMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MosaicTileMaker.getStats() return {clayStock=MosaicTileMaker.clayStock,glassStock=MosaicTileMaker.glassStock,marbleStock=MosaicTileMaker.marbleStock,silverStock=MosaicTileMaker.silverStock,goldStock=MosaicTileMaker.goldStock,jewelStock=MosaicTileMaker.jewelStock,pearlStock=MosaicTileMaker.pearlStock,productStock=MosaicTileMaker.productStock,numBuildings=#MosaicTileMaker.buildings,hasMaker=MosaicTileMaker.maker~=nil,makerName=MosaicTileMaker.maker and MosaicTileMaker.maker.name or "—",makerSkill=MosaicTileMaker.maker and MosaicTileMaker.maker.skill or 0,activeMaking=#MosaicTileMaker.activeMaking,totalProducts=MosaicTileMaker.totalProducts} end
return MosaicTileMaker
